    {
      "action": "group_by",
      "params": "Computer, Account, EventID, Activity",
      "explanation": "Group results by computer, account, event ID, and activity type"
    },
    {
      "action": "eval",
      "params": "timestamp = StartTimeUtc, AccountCustomEntity = Account, HostCustomEntity = Computer",
      "explanation": "Create calculated fields for timestamp, account entity, and host entity"
    }
  ]
} [end of text]

